PROGRAM ST490_AMR_OVERLAMNING
VAR
    steg        : INT := 0;
    tmrXfr      : TON;
    trigReset   : R_TRIG;
    trigDone    : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xXfrAktiv   : BOOL := FALSE;
    xDoneSedd   : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. Den har logiken ror inte
   sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);
trigDone(CLK := ST490_XFR_DONE);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* --- larmkallorna samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter det don den ska stoppa. --- *)

(* Lastbararen i mottagningslaget ska vaga 10,0 till 20,0 kg. En tom KLT 6280
   vager 2,4 kg och en fylld 14,4 kg; utanfor fonstret star det fel barare i
   laget och stationen far inte kvittera in den i flodet. *)
IF ST490_PEC_IN AND (ST490_LOD_WGT < 10.0 OR ST490_LOD_WGT > 20.0) THEN
    xLarm := TRUE;
END_IF;

(* Nagot star i overlamningsgapet utan att en overforing pagar: en lastbarare
   har kilat sig mellan AMR-dacket och stationens bana. *)
IF ST490_PEC_GAP AND NOT xXfrAktiv THEN
    xLarm := TRUE;
END_IF;

(* Tidsvakt over hela handskakningen. Overforingsstrackan ar 1000 mm och banan
   gar 400 mm/s, alltsa 2,5 s ren gangtid; vakten 4,0 s lamnar 1,5 s. *)
tmrXfr(IN := xXfrAktiv, PT := T#4s);
IF tmrXfr.Q THEN
    xLarm := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;

xDriftsklar := EMG_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    ST490_XFR_ACK := FALSE;
    ST490_XFR_RST := FALSE;
    xXfrAktiv := FALSE;
    xDoneSedd := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST490_XFR_RST := FALSE;
            xDoneSedd := FALSE;
            (* Kvittensen ges forst nar dockningen ar bekraftad OCH
               mottagningslaget ar tomt. Den ar ett loften om plats. *)
            IF ST490_XFR_REQ AND ST490_DOK_OK AND NOT ST490_PEC_IN THEN
                ST490_XFR_ACK := TRUE;
                xXfrAktiv := TRUE;
                steg := 1;
            END_IF;
        1:
            (* Lastbararen har natt mottagningslaget: inbjudan dras tillbaka. *)
            IF ST490_PEC_IN THEN
                ST490_XFR_ACK := FALSE;
            END_IF;
            IF trigDone.Q THEN
                xDoneSedd := TRUE;
            END_IF;
            (* Nollstallningen kommer pa AMR:ns DONE, aldrig pa en niva. *)
            IF ST490_PEC_IN AND xDoneSedd THEN
                ST490_XFR_RST := TRUE;
                xXfrAktiv := FALSE;
                steg := 2;
            END_IF;
        2:
            IF NOT ST490_XFR_REQ OR NOT ST490_XFR_DONE THEN
                ST490_XFR_RST := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Stationens bana drar in lastbararen. Aldrig utan bekraftad dockning: utan
   AMR:n i lage finns inget dack att rulla over ifran, och lastbararen kilar
   sig i gapet. Aldrig nar mottagningslaget redan ar upptaget. *)
ST490_CNV_RUN := xDriftsklar AND xXfrAktiv AND ST490_DOK_OK AND NOT ST490_PEC_IN;
END_PROGRAM

